// When the battle scene exists and g_RubyTentaclesSpriteResourceHandle is zero, initializes a
// default-duration resource record with type zero, builds weapon/weapon1 into the local path buffer
// and calls Gfx_LoadModelTableIfAbsent with resource ID 1, g_WeaponFxRubyTentaclesSmokeSpriteRecord
// metadata, the global output slot and the scene's model-table bank. Otherwise does nothing.
// FUNCTION: FF7 0x0044a510
void __cdecl BattleFx_WeaponLoadResRubyTentacles(void)
{
    GfxModelTableBank *sceneContext;
    GfxResourceRequest requestBuffer;
    int resultId;
    char pathBuffer[200];
    GfxResourceRequest *request;
    int recordAddr;

    if (g_pBattle3dScene != 0 && g_RubyTentaclesSpriteResourceHandle == 0) {
        resultId = 1;
        recordAddr = (int)g_WeaponFxRubyTentaclesSmokeSpriteRecord;
        sceneContext = (GfxModelTableBank *)(g_pBattle3dScene->modelTableBank);
        request = &requestBuffer;
        Gfx_InitResourceRequest(request);
        request->groupTag = 0;
        // STRING: FF7 0x007e2a68
        request->resourcePath = BattleFx_BuildResourcePath("weapon/weapon1", pathBuffer);
        Gfx_LoadModelTableIfAbsent(resultId, recordAddr, request, &g_RubyTentaclesSpriteResourceHandle, sceneContext);
    }
}

