// Per-frame step of the sting envelope, which does nothing while g_BattleIsPaused is set. The
// envelope amplitude rises over attackFrames, holds over sustainFrames and falls over
// releaseFrames, using 0x1000 as full scale. Each frame it sets g_BattleCameraTransform.posY to the
// envelope value, negated on even frames, and advances frame. When the release is over it sets step
// to 0xFFFF and clears posY.
// FUNCTION: FF7 0x0044bcbd
void __cdecl BattleFx_RubyTentaclesEnvelopeTask(void)
{
    int localFrame;
    int envValue;
    BattleFxRubyTentaclesEnvelope *task;
    int wobble;
    int ratio;

    task = (BattleFxRubyTentaclesEnvelope *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    localFrame = task->frame;
    if (localFrame < task->attackFrames) {
        ratio = (localFrame << 0xC) / task->attackFrames;
        envValue = task->amplitude * ratio >> 0xC;
    } else {
        localFrame -= task->attackFrames;
        if (localFrame < task->sustainFrames) {
            envValue = task->amplitude;
        } else {
            localFrame -= task->sustainFrames;
            if (localFrame < task->releaseFrames) {
                ratio = (localFrame << 0xC) / task->releaseFrames;
                envValue = task->amplitude * (0x1000 - ratio) >> 0xC;
            } else {
                task->step = 0xFFFF;
                g_BattleCameraTransform.posY = 0;
                return;
            }
        }
    }
    if ((task->frame & 1) != 0) {
        wobble = envValue;
    } else {
        wobble = -envValue;
    }
    g_BattleCameraTransform.posY = wobble;
    (task->frame)++;
}

// Prepares the sting offscreen pair. The four offscreen argument words take the battle viewport
// origin, with 0x40 and 0x80 in the last two words, or 0x80 and 0xFF when g_BattleUiScalingMode is
// 2. The direction matrix is copied from g_RubyTentaclesRotationMatrix, and its dwordB is negated when
// the Y angle of g_RubyTentaclesRotationAngles is zero. That direction matrix is multiplied by
// g_RubyTentaclesTransformMatrix, and the pair is submitted through BattleFx_RubyTentaclesSubmitOffscreenPair.
// FUNCTION: FF7 0x0044bde6
void __cdecl BattleFx_RubyTentaclesPrepareOffscreenPair(void)
{
    int w[8];

    if (g_BattleUiScalingMode != 2) {
        g_RubyTentaclesOffscreenRect.viewportX = *(short *)&g_BattleViewportOriginX;
        g_RubyTentaclesOffscreenRect.viewportY = *(short *)&g_BattleViewportOriginY;
        g_RubyTentaclesOffscreenRect.viewportW = 0x40;
        g_RubyTentaclesOffscreenRect.viewportH = 0x80;
    } else {
        g_RubyTentaclesOffscreenRect.viewportX = *(short *)&g_BattleViewportOriginX;
        g_RubyTentaclesOffscreenRect.viewportY = *(short *)&g_BattleViewportOriginY;
        g_RubyTentaclesOffscreenRect.viewportW = 0x80;
        g_RubyTentaclesOffscreenRect.viewportH = 0xFF;
    }
    g_RubyTentaclesDirectionMatrix.m22 = *(short *)&g_RubyTentaclesRotationMatrix;
    g_RubyTentaclesDirectionMatrix.m00 = g_RubyTentaclesDirectionMatrix.m22;
    if (g_RubyTentaclesRotationAngles.vy != 0) {
        g_RubyTentaclesDirectionMatrix.transZ = *(int *)((char *)&g_RubyTentaclesRotationMatrix + 0x1A);
    } else {
        g_RubyTentaclesDirectionMatrix.transZ = -*(int *)((char *)&g_RubyTentaclesRotationMatrix + 0x1A);
    }
    MultiplyMatrix(&g_RubyTentaclesTransformMatrix, (short *)&g_RubyTentaclesDirectionMatrix, w);
    BattleFx_RubyTentaclesSubmitOffscreenPair(w, (BattleFxRubyTentaclesOffscreenRecord *)&g_RubyTentaclesOffscreenRect);
}

// Submits the sting offscreen pair. Sets the rotation and translation matrices from matrix. When
// g_pBattle3dScene has a non-zero stageId, it acquires two offscreen requests from
// Battle3d_AcquireOffscreenRequest. Each gets the part mesh from BattleStage_GetPartMesh, the
// matrix as the request's transposed float 4x4 model matrix, and the rectangle from record. The first uses
// render flags 4 and stores its slot in g_RubyTentaclesOpcode9OffscreenSlotIndex; the second uses 0xC and
// stores g_RubyTentaclesOpcodeBOffscreenSlotIndex.
// FUNCTION: FF7 0x0044bebd
void __cdecl BattleFx_RubyTentaclesSubmitOffscreenPair(void *matrix, BattleFxRubyTentaclesOffscreenRecord *record)
{
    GfxOffscreenRequest *pRequest;
    int partHandle;

    SetRotMatrix(matrix);
    SetTransMatrix(matrix);
    if (g_pBattle3dScene != 0 && g_pBattle3dScene->stageId != 0) {
        partHandle = g_pBattle3dScene->stageId;
        pRequest = (GfxOffscreenRequest *)Battle3d_AcquireOffscreenRequest();
        if (pRequest != 0) {
            pRequest->kind = 1;
            pRequest->mesh = (int)BattleStage_GetPartMesh(1, (Battle3dStageRecord *)partHandle);
            GtePsxMatrixToFloat4x4Transposed(matrix, pRequest->modelMatrix);
            pRequest->pageFillEnabled = 0;
            pRequest->renderKind = 4;
            pRequest->blendMode = BLEND_ADDITIVE;
            pRequest->blendMode = BLEND_NONE;
            pRequest->viewportX = record->rectX;
            pRequest->viewportY = record->rectY;
            pRequest->viewportW = record->rectW;
            pRequest->viewportH = record->rectH;
            pRequest->pageFillStepX = 1;
            pRequest->pageFillStepY = 1;
            g_RubyTentaclesOpcode9OffscreenSlotIndex = pRequest->slotIndex;
        }
        pRequest = (GfxOffscreenRequest *)Battle3d_AcquireOffscreenRequest();
        if (pRequest != 0) {
            pRequest->kind = 1;
            pRequest->mesh = (int)BattleStage_GetPartMesh(1, (Battle3dStageRecord *)partHandle);
            GtePsxMatrixToFloat4x4Transposed(matrix, pRequest->modelMatrix);
            pRequest->pageFillEnabled = 0;
            pRequest->renderKind = 0xC;
            pRequest->blendMode = BLEND_ADDITIVE;
            pRequest->blendMode = BLEND_NONE;
            pRequest->viewportX = record->rectX;
            pRequest->viewportY = record->rectY;
            pRequest->viewportW = record->rectW;
            pRequest->viewportH = record->rectH;
            pRequest->pageFillStepX = 1;
            pRequest->pageFillStepY = 1;
            g_RubyTentaclesOpcodeBOffscreenSlotIndex = pRequest->slotIndex;
        }
    }
}

// Per-frame model task for the sting. Unless g_BattleIsPaused is set, it advances timer in three
// phases. Below 0x1C it blends the base model vertices toward the animation frame at weight
// timer/0x1C (4096ths), recomputing the deltas every fourth step, and emits vertex particles. The
// next 0x2D steps hold the blend weight at zero, and after that it kills the slot (ownerSlot =
// 0xFFFF). Every frame it then sets up the rotation, scale and translation matrices, multiplies by
// g_RubyTentaclesCombinedMatrix, and refreshes the global transform state.
