// Computes the per-vertex deltas for one animation frame. The vertex count is the first word of
// srcList divided by 8, and the vertices start 4 bytes in. Each delta is the source vertex minus
// the matching reference vertex from baseVerts, written as deltaX, deltaY and deltaZ into deltaOut.
// All three arrays advance 8 bytes per vertex.
// FUNCTION: FF7 0x0044d68e
void __cdecl BattleFx_RubyTentaclesComputeVertexDeltas(struct RubyTentaclesBaseModelVertices *srcList, SVECTOR *baseVerts, SVECTOR *deltaOut)
{
    SVECTOR *sourceVert;
    int vertCnt;
    int i;

    vertCnt = srcList->byteCount / 8;
    sourceVert = (SVECTOR *)&srcList->vertexPtr;
    for (i = 0; i < vertCnt; i++) {
        deltaOut->vx = sourceVert->vx - baseVerts->vx;
        deltaOut->vy = sourceVert->vy - baseVerts->vy;
        deltaOut->vz = sourceVert->vz - baseVerts->vz;
        sourceVert++;
        baseVerts++;
        deltaOut++;
    }
}

// Writes the blended vertices of one frame into dstList. The count and layout are as in
// BattleFx_RubyTentaclesComputeVertexDeltas. The weight argument is replaced by 0x1000 minus itself, and
// each vertex is its base vertex plus its delta scaled by that weight in 4096ths.
// FUNCTION: FF7 0x0044d72b
void __cdecl BattleFx_RubyTentaclesBlendVertexDeltas(struct RubyTentaclesBaseModelVertices *dstList, SVECTOR *baseVerts, SVECTOR *deltas, int blendWeight)
{
    SVECTOR *destCursor;
    int vertCnt;
    int i;

    vertCnt = dstList->byteCount / 8;
    destCursor = (SVECTOR *)&dstList->vertexPtr;
    blendWeight = 0x1000 - blendWeight;
    for (i = 0; i < vertCnt; i++) {
        destCursor->vx = baseVerts->vx + (deltas->vx * blendWeight >> 0xC);
        destCursor->vy = baseVerts->vy + (deltas->vy * blendWeight >> 0xC);
        destCursor->vz = baseVerts->vz + (deltas->vz * blendWeight >> 0xC);
        destCursor++;
        baseVerts++;
        deltas++;
    }
}

// Builds the Sting model matrix from the angles g_RubyTentaclesParticleModelAngles and the scale
// g_RubyTentaclesParticleModelScale, then spends the accumulated emission budget at
// g_RubyTentaclesBurstAccumulator1 in 0x100 steps. Each step scans the 0x155 model vertices
// from a random start for one whose delta Y at g_RubyTentaclesBlendedVertexBuffer is positive,
// allocates a particle slot running BattleFx_RubyTentaclesParticleSpriteTask, places it at the transformed
// vertex (mirroring X on alternate particles) and gives it a random 0x1800..0x1FFF speed.
// FUNCTION: FF7 0x0044d7eb
void BattleFx_RubyTentaclesEmitVertexParticles(void)
{
#pragma pack(push, 1)
    /* Locals by stack slot: see FRAME UNION in lib/codegen.h. */
    union {
        unsigned char storage[76];
        int speed;
        struct { unsigned char pad_to_4[0x4]; int startIndex; };
        struct { unsigned char pad_to_8[0x8]; PsxMatrix modelMatrix; };
        struct { unsigned char pad_to_28[0x28]; int posX; };
        struct { unsigned char pad_to_2C[0x2C]; short posY; };
        struct { unsigned char pad_to_30[0x30]; short posZ; };
        struct { unsigned char pad_to_38[0x38]; int vertexIndex; };
        struct { unsigned char pad_to_3C[0x3C]; BattleFxRubyTentaclesRadialSprite *particleRecord; };
        struct { unsigned char pad_to_40[0x40]; int scanIndex; };
        struct { unsigned char pad_to_44[0x44]; int pointDepth; };
        struct { unsigned char pad_to_48[0x48]; int vertexBase; };
    } frame;
#pragma pack(pop)

    frame.vertexBase = (int)&g_RubyTentaclesBaseModelVertices.vertexPtr;
    RotMatrixXYZ((int *)&g_RubyTentaclesParticleModelAngles, &frame.modelMatrix);
    ScaleMatrix(&frame.modelMatrix, (int *)&g_RubyTentaclesParticleModelScale);
    frame.modelMatrix.t[0] = 0x3E8;
    frame.modelMatrix.t[1] = 0;
    frame.modelMatrix.t[2] = 0;
    SetRotMatrix(&frame.modelMatrix);
    SetTransMatrix(&frame.modelMatrix);
    g_RubyTentaclesBurstAccumulator1 += 0x300;
    while (g_RubyTentaclesBurstAccumulator1 >= 0x100) {
        frame.startIndex = rand() % 0x155;
        for (frame.scanIndex = 0; frame.scanIndex < 0x155; frame.scanIndex++) {
            frame.vertexIndex = (frame.startIndex + frame.scanIndex) % 0x155;
            frame.vertexIndex = (frame.startIndex + frame.scanIndex) % 0x155;
            if (((SVECTOR *)&g_RubyTentaclesBlendedVertexBuffer)[frame.vertexIndex].vy > 0) {
                frame.particleRecord = (BattleFxRubyTentaclesRadialSprite *)BATTLE_NEW_TASK_SLOT(BattleFx_RubyTentaclesParticleSpriteTask);
                RotTransPoint((void *)(frame.vertexBase + frame.vertexIndex * 8), &frame.posX, &frame.pointDepth);
                frame.particleRecord->posX = *(short *)&frame.posX;
                frame.particleRecord->posY = frame.posY;
                frame.particleRecord->posZ = frame.posZ;
                if (g_RubyTentaclesToggleFlag != 0) {
                    frame.particleRecord->posX = -frame.particleRecord->posX;
                }
                g_RubyTentaclesToggleFlag ^= 1;
                if (DEAD_IN_RETAIL != 0) {
                    frame.speed = 0x2000;
                } else {
                    frame.speed = rand() % 0x800 + 0x1800;
                }
                frame.particleRecord->size = *(short *)&frame.speed;
                break;
            }
        }
        g_RubyTentaclesBurstAccumulator1 -= 0x100;
    }
}

// Per-frame handler for a sprite effect: fetches the table entries for g_RubyTentaclesSpriteResourceHandle into
// g_RubyTentaclesCurrentTableGroup and g_RubyTentaclesCurrentTableGroup.drawObj, draws the sprite through BattleFx_RubyTentaclesDrawSprite at the record's position
// with its frame and size, and while unpaused and the sprite exists advances the
// frame, retiring the record with 0xFFFF when the frame reaches the sprite's frame count (the
// second word of its first entry).
// FUNCTION: FF7 0x0044d9a3
void __cdecl BattleFx_RubyTentaclesParticleSpriteTask(void)
{
    BattleFxRubyTentaclesParticleSprite *task;

    task = (BattleFxRubyTentaclesParticleSprite *)BATTLE_CURRENT_TASK_SLOT;
    g_RubyTentaclesCurrentTableGroup.spriteGroup = (BattleFxSpriteGroup *)Gfx_ModelTableGetLoadedRecord(0, g_RubyTentaclesSpriteResourceHandle);
    g_RubyTentaclesCurrentTableGroup.drawObj = Gfx_ModelTableGetSpriteObject(0, g_RubyTentaclesSpriteResourceHandle);
    BattleFx_RubyTentaclesDrawSprite(&task->position, task->frame, task->size);
    if (g_BattleIsPaused == 0 && g_RubyTentaclesCurrentTableGroup.spriteGroup != 0) {
        (task->frame)++;
        if (task->frame == g_RubyTentaclesCurrentTableGroup.spriteGroup->header->frameCount) {
            task->ownerSlot = BATTLE_TASK_FREE;
        }
    }
}

// Submits one sprite draw: the table entries for g_RubyTentaclesSpriteResourceHandle go into g_RubyTentaclesSpriteDrawRequest and
// g_RubyTentaclesSpriteDrawRequest.drawObj, BattleFx_RubyTentaclesPlaceSpritePosition places it at position with size size and depth -1000, the frame frameIndex goes
// to g_RubyTentaclesSpriteDrawRequest.frameIndex, and BattleFx_SubmitSpriteDraw chains the packet onto g_BattleOverlayDrawListHead with the bank
// at g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED and kind 0xC.
// FUNCTION: FF7 0x0044da4b
void __cdecl BattleFx_RubyTentaclesDrawSprite(void *position, int frameIndex, int size)
{
    g_RubyTentaclesSpriteDrawRequest.spriteGroup = (BattleFxSpriteGroup *)Gfx_ModelTableGetLoadedRecord(0, g_RubyTentaclesSpriteResourceHandle);
    g_RubyTentaclesSpriteDrawRequest.drawObj = Gfx_ModelTableGetSpriteObject(0, g_RubyTentaclesSpriteResourceHandle);
    BattleFx_RubyTentaclesPlaceSpritePosition(position, (short)size, 0xFFFFFC18);
    g_RubyTentaclesSpriteDrawRequest.frameIndex = frameIndex;
    g_BattleOverlayDrawListHead = BattleFx_SubmitSpriteDraw(&g_RubyTentaclesSpriteDrawRequest, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleOverlayDrawListHead);
}

// Places a sprite particle at position, storing stateWord in g_RubyTentaclesParticleState.stateWord. It
// sets the placement matrix rows from stateWord and the rotation and translation matrices from
// g_RubyTentaclesCombinedMatrix, then transforms position into the posXDword, posYDword and posZDword
// fields. When offset is not zero the point is pushed along the normalized vector by offset in
// 4096ths, though the Y and Z terms use ny and dirZ, which the normalize call does not set in this
// code. Returns the address of placement matrix row 0.
// FUNCTION: FF7 0x0044dac0
int __cdecl BattleFx_RubyTentaclesPlaceSpritePosition(void *position, short stateWord, int offset)
{
    int otz;
    VECTOR normal;

    g_RubyTentaclesParticleState.stateWord = stateWord;
    g_RubyTentaclesPlacementMatrixRow1 = (g_RubyTentaclesParticleState.stateWord);
    g_RubyTentaclesPlacementMatrixRow0 = g_RubyTentaclesPlacementMatrixRow1;
    SetRotMatrix(&g_RubyTentaclesCombinedMatrix.matrix);
    SetTransMatrix(&g_RubyTentaclesCombinedMatrix.matrix);
    RotTransPoint(position, (int *)&g_RubyTentaclesParticleState.posXDword, &otz);
    if (offset != 0) {
        NormalizeVectorFixed((int *)&g_RubyTentaclesParticleState.posXDword, &normal);
        g_RubyTentaclesParticleState.posXDword += normal.vx * offset >> 0xC;
        g_RubyTentaclesParticleState.posYDword += normal.vy * offset >> 0xC;
        g_RubyTentaclesParticleState.posZDword += normal.vz * offset >> 0xC;
    }
    SetRotMatrix(&g_RubyTentaclesPlacementMatrixRow0);
    SetTransMatrix(&g_RubyTentaclesPlacementMatrixRow0);
    return (int)&g_RubyTentaclesPlacementMatrixRow0;
}

// Allocates an effect record running BattleFx_RubyTentaclesEffectRecordTask and stores actor as its first word.
// FUNCTION: FF7 0x0044db9b
void BattleFx_RubyTentaclesSpawnEffectRecord(short actor)
{
    BattleFxRubyTentaclesEffectRecord *rec;

    rec = (BattleFxRubyTentaclesEffectRecord *)BATTLE_NEW_TASK_SLOT(BattleFx_RubyTentaclesEffectRecordTask);
    rec->actorIndex = actor;
}

// Per-frame step for a sting effect record, which drives the actor at p->actorIndex. Unless
// g_BattleIsPaused is set, on timer 0 it sets the actor posY to 0x1388. For timer below 0xF it
// lowers posY by 0x14D each frame, clears drawFlags bit 0x04 and zeroes posY at timer 0xE, and
// spawns a radial particle burst at the actor position using g_RubyTentaclesParticleProgress1, which it
// advances by 0x100 per frame. Otherwise it sets actorIndex to 0xFFFF. Unless paused, the timer
// then advances; the actor's attached parts are drawn into the overlay draw list every frame.
// FUNCTION: FF7 0x0044dbc8
void __cdecl BattleFx_RubyTentaclesEffectRecordTask(void)
{
    BattleFxRubyTentaclesEffectRecord *task;

    task = (BattleFxRubyTentaclesEffectRecord *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused == 0) {
        if (task->timer == 0) {
            g_BattleActorRecords[task->actorIndex].posY = 0x1388;
            (task->timer)++;
            return;
        }
        if (task->timer < 0xF) {
            g_BattleActorRecords[task->actorIndex].posY -= 0x14D;
            if (task->timer == 0xE) {
                g_BattleActorRecords[task->actorIndex].drawFlags &= 0xFB;
                g_BattleActorRecords[task->actorIndex].posY = 0;
            }
            g_RubyTentaclesParticleProgress1 += 0x100;
            g_RubyTentaclesParticleProgress1 = BattleFx_RubyTentaclesSpawnRadialParticleBurst((Vec3sPacked *)&g_BattleActorRecords[task->actorIndex].posX, g_RubyTentaclesParticleProgress1);
        } else {
            task->actorIndex = 0xFFFF;
        }
        (task->timer)++;
    }
    g_BattleOverlayDrawListHead = BattleFx_RubyTentaclesDrawRecordAttachedParts(task->actorIndex, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, (BattleFxRubyTentaclesMeshPacket *)g_BattleOverlayDrawListHead);
}

