// Per-frame record task for the Weapon1 effect. Unless paused, it sets bit 4 of the actor's
// drawFlags on frame 0, and while frameCount is below 0x1E it moves the actor's posY by 0xA6 and
// advances g_RubyTentaclesParticleProgress2 by 0x100 for a radial particle burst. From frame 0x1E on it
// clears the record's actorIndex to 0xFFFF. The attached parts are drawn into the overlay draw list
// on every call, paused or not.
// FUNCTION: FF7 0x0044e6e9
void __cdecl BattleFx_RubyTentaclesRecordTask(void)
{
    BattleFxRubyTentaclesRecord *task;

    task = (BattleFxRubyTentaclesRecord *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused == 0) {
        if (task->frameCount == 0) {
            g_BattleActorRecords[task->actorIndex].drawFlags |= 4;
            (task->frameCount)++;
            return;
        }
        if (task->frameCount < 0x1E) {
            g_BattleActorRecords[task->actorIndex].posY += 0xA6;
            g_RubyTentaclesParticleProgress2 += 0x100;
            g_RubyTentaclesParticleProgress2 = BattleFx_RubyTentaclesSpawnRadialParticleBurst((Vec3sPacked *)&g_BattleActorRecords[task->actorIndex].posX, g_RubyTentaclesParticleProgress2);
        } else {
            task->actorIndex = 0xFFFF;
        }
        (task->frameCount)++;
    }
    g_BattleOverlayDrawListHead = BattleFx_RubyTentaclesDrawRecordAttachedParts(task->actorIndex, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, (BattleFxRubyTentaclesMeshPacket *)g_BattleOverlayDrawListHead);
}

